<template>
    <div class="page">
        <app-header :title='tits' :istop="num"></app-header>
        <div class="main">
            <van-form @submit="submitForm">
                <div class="formCol">
                    <div class="item">
                        <div class="label">子账户用户名</div>
                        <div class="item-rt">
                            {{ ruleForm.account }}
                        </div>
                    </div>
                    <div class="item">
                        <div class="label">子账号昵称</div>
                        <div class="item-rt">
                            <input  v-model="ruleForm.nickName" class="addInput" />
                        </div>
                    </div>
                    <div class="item">
                        <div class="label">状态</div>
                        <div class="item-rt">
                            <van-radio-group v-model="ruleForm.status" direction="horizontal">
                                <van-radio :name="1">启用</van-radio>
                                <van-radio :name="2">禁用</van-radio>
                                <van-radio :name="3">冻结</van-radio>
                            </van-radio-group>
                        </div>
                    </div>
                    <div class="item">
                        <div class="label">登录密码</div>
                        <div class="item-rt">
                            <input  v-model="ruleForm.passwd"  class="addInput" />
                        </div>
                    </div>
                    <div class="item">
                        <div class="label">IP绑定</div>
                        <div class="item-rt">
                            <input  v-model="ruleForm.whiteIp"  class="addInput" />
                        </div>
                    </div>
                    <div class="item" style="align-items: baseline">
                        <div class="label">二次验证</div>
                        <div class="item-rt">
                            <span v-if="subAccountInfo.isGoogle==2">未绑定</span>
                            <span v-if="subAccountInfo.isGoogle==1" style="color:#62bd12;margin-right:10px">已启动</span>
                            <span v-if="subAccountInfo.isGoogle==1"  @click="delMyao" class="blue pointer">重置</span>
                        </div>
                    </div>
                    <div class="item">
                        <div class="label">菜单显示</div>
                        <div class="item-rt" style="padding-top:5px;">
                            <van-checkbox-group class="checkbox" direction="horizontal"  v-model="ruleForm.ridios" >
                                <template v-for="(item,index) in proxySubLimit" :key="index+1">
                                    <van-checkbox v-show="item.show" style="margin-bottom:5px;width:110px;height:20px;" :name="item.id"  shape="square" >{{item.name}}</van-checkbox>
                                </template>
                            </van-checkbox-group>
                        </div>
                    </div>
                    <div class="fobtn">
                        <div class="fobcanl" @click="cancelForm" >取消</div>
                        <div class="fobmits" @click="submitForm" >确定</div>
                    </div>
                </div>
            </van-form>
        </div>
    </div>
</template>
<script setup lang="ts">
import { ref, reactive, onMounted } from 'vue'
import { useRouter,useRoute } from 'vue-router'
import { useUserStore } from '@/store/user'
import { useAppStore } from '@/store/index'
import { useTimeUtils } from '@/utils/time'
import useMd5 from '@/utils/useMd5'
import { showToast, showConfirmDialog,showLoadingToast } from 'vant'
import nzhcn from "nzh/cn";

// 路由和状态管理
const router = useRouter()
const route = useRoute()
const userStore = useUserStore()
const appStore = useAppStore()
const userTime = useTimeUtils()
const md5 = useMd5();
// 加载状态
const loading = ref(false)

// 菜单列表
const proxySubLimit = ref([
    { name: '即时注单', id: 4, show: false },
    { name: '数据分析', id: 5, show: false },
    { name: '用户管理', id: 6, show: false },
    { name: '赔率设置', id: 7, show: false },
    { name: '个人资料', id: 8, show: false },
    { name: '报表查询', id: 9, show: false },
    { name: '开奖记录', id: 10, show: false },
    { name: '手动降倍', id: 15, show: false },
    { name: '货量降倍', id: 11, show: false },
    { name: '会员降倍', id: 12, show: false },
    { name: '自动降倍', id: 13, show: false },
])
// 表单数据
const ruleForm = reactive({
    account: '',
    nickName: '',
    status: 1,
    passwd: '',
    whiteIp: '',
    menuList: [],
    lotteryList: [],
    ridios: [],
    password: '',
    role: 4
})
const num = ref(3)
const tits = ref('子账号修改')
const props = defineProps(['id'])
const subAccountInfo = ref('')


// ==================== 生命周期 ====================
onMounted(() => {
    getSubAccountInfo()
})
const delMyao = async()=>{
    loading.value = true
    try {
        await userStore.delGoogle(props.id)
        showToast({
            message: '解绑成功',
            className: 'custom-toast',
            duration: 1000  // 自定义显示时间
        });
        await getSubAccountInfo()
    } catch (error) {
        console.log('解绑失败')
    } finally {
        loading.value = false
    }
}
const getSubAccountInfo = async() =>{
    loading.value = true
    try {
        const res = await userStore.getQueryOrg(props.id)
        ruleForm.account = res.data.account;
        ruleForm.nickName = res.data.nickName;
        ruleForm.status = res.data.status;
        ruleForm.id = res.data.id;
        ruleForm.isDefault = res.data.isDefault;
        ruleForm.whiteIp = res.data.whiteIp;
        ruleForm.ridios = res.data.menuList;
        getProxySubLimit();
    } catch (error) {
        console.log('解绑失败')
    } finally {
        loading.value = false
    }
}
// 获取子账号菜单权限
const getProxySubLimit = async () => {
    try {
        const res = await userStore.getMenu()
        if (res.data && res.data.length > 0) {
            proxySubLimit.value.forEach(its => {
                res.data.forEach(item => {
                    if (item == its.id) {
                        its.show = true
                    }
                })
            })
        }
    } catch (error) {
        console.log('getProxySubLimit error:', error)
    }
}
const submitForm = () => {
    ruleForm.menuList=[];
    ruleForm.menuList = ruleForm.ridios
    let paw = ruleForm.passwd.toLowerCase();
    ruleForm.password=ruleForm.passwd?md5(paw):'';
    ruleForm.role = 4;
    editsubaccount(ruleForm);
}
const  editsubaccount = async(data) =>{
     try {
        const res = await userStore.subUpdate(data)
        if(res.code==200){
          router.push({path: '/subaccount'})
        }
    } catch (error) {
        console.log('getProxySubLimit error:', error)
    }
}
const cancelForm = () =>{
    router.push({
        path: '/subaccount'
    })
}
</script>
<style scoped>
.page{
    height:100vh;
    background-color: var(--blue-surface-b-50);
}
</style>
